@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if (target == null || resultMap == null) return;
    // Add all vertices to the target graph
    for (V v : resultMap.values()){
        if (v == null) continue;
        try{
            target.addVertex(v);
        }catch (Exception ignored){}
    }
    // Build a list of vertices to partition into two sets
    List<V> vertices = new ArrayList<>(resultMap.values());
    int n = vertices.size();
    if (n < 2) return; // need at least two vertices for bipartite
    int mid = n / 2;
    List<V> left = vertices.subList(0, mid);
    List<V> right = vertices.subList(mid, n);
    // Connect every vertex in left to every vertex in right
    for (V u : left){
        if (u == null) continue;
        for (V w : right){
            if (w == null) continue;
            try{
                target.addEdge(u, w);
            }catch (Exception ignored){}
        }
    }
}

