public Mappings diffStructure(String tableName, Mappings mappings) {
    if (tableName == null || tableName.isEmpty() || mappings == null) {
        return new Mappings();
    }
    try {
        // Retrieve the current mapping for the given table name
        Mappings current = getMapping(tableName);
        if (current == null) {
            return new Mappings();
        }

        Map<String, Object> currentProps = current.getProperties();
        Map<String, Object> inputProps = mappings.getProperties();

        if (currentProps == null) {
            return new Mappings();
        }

        Map<String, Object> diffProps = new LinkedHashMap<>();
        for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
            String key = entry.getKey();
            // Skip the _source configuration to avoid update conflicts
            if ("_source".equals(key)) {
                continue;
            }
            // Add only those fields that are not present in the input mappings
            if (inputProps == null || !inputProps.containsKey(key)) {
                diffProps.put(key, entry.getValue());
            }
        }

        Mappings diff = new Mappings();
        diff.setProperties(diffProps);
        return diff;
    } catch (Exception e) {
        // In case of any unexpected error, return an empty mapping
        return new Mappings();
    }
}

