protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (start > end) {
        return ranges;
    }
    if (FETCH_DATA_DURATION <= 0) {
        ranges.add(new TimeRange(start, end));
        return ranges;
    }
    long currentStart = start;
    while (currentStart <= end) {
        long maxEnd = currentStart + FETCH_DATA_DURATION - 1;
        if (maxEnd < 0 || maxEnd > end) { // handle overflow or exceed end
            maxEnd = end;
        }
        ranges.add(new TimeRange(currentStart, maxEnd));
        if (maxEnd == end) {
            break;
        }
        currentStart = maxEnd + 1;
    }
    return ranges;
}

