private static boolean endsWith(final String str,final String suffix,final boolean ignoreCase){
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    if (suffix.isEmpty()) {
        return true;
    }
    if (suffix.length() > str.length()) {
        return false;
    }
    if (!ignoreCase) {
        return str.endsWith(suffix);
    }
    return str.regionMatches(true, str.length() - suffix.length(), suffix, 0, suffix.length());
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Remove leading '/' if present (absolute path)
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    // Split on '/' to get individual segments
    String[] parts = path.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String decoded = part;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; wrap in RuntimeException
                throw new RuntimeException(e);
            }
        }
        // Assuming PathSegmentImpl has a constructor that accepts original and decoded values
        segments.add(new PathSegmentImpl(part, decoded));
    }
    return segments;
}

