@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (!Character.class.isAssignableFrom(type) && type != char.class) {
        throw new IllegalArgumentException("Target type must be Character or char");
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() == 1) {
            return s.charAt(0);
        } else {
            throw new Exception("Cannot convert String to Character: length != 1");
        }
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return (char) intVal;
    }
    throw new Exception("Cannot convert type " + value.getClass().getName() + " to Character");
}

public static int nextPrime(int desiredCapacity) {
    // Handle non-positive or very small capacities
    if (desiredCapacity <= 2) {
        return 2;
    }

    // Start searching from the desired capacity
    int candidate = desiredCapacity;
    // Ensure candidate is odd (except for 2 which is already handled)
    if (candidate % 2 == 0) {
        candidate++;
    }

    // Upper bound for the search when desiredCapacity >= 1000
    int upperBound = Integer.MAX_VALUE;
    if (desiredCapacity >= 1000) {
        // 11% tolerance, add 1 to avoid rounding issues
        upperBound = (int) (desiredCapacity * 1.11) + 1;
    }

    while (true) {
        // Check if candidate is prime
        boolean isPrime = true;
        if (candidate < 2) {
            isPrime = false;
        } else if (candidate == 2) {
            isPrime = true;
        } else if (candidate % 2 == 0) {
            isPrime = false;
        } else {
            int limit = (int) Math.sqrt(candidate);
            for (int i = 3; i <= limit; i += 2) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
                }
            }
        }

        if (isPrime) {
            return candidate;
        }

        // Move to the next odd number
        candidate += 2;

        // If we exceeded the upper bound for large capacities, stop searching
        if (desiredCapacity >= 1000 && candidate > upperBound) {
            // Return the first prime found beyond the 11% range
            return candidate;
        }
    }
}

