private JsonObject convertProperties(List<KeyStringValuePair> properties){
    JsonObject json = new JsonObject();
    if (properties == null) {
        return json;
    }
    for (KeyStringValuePair pair : properties) {
        if (pair == null) {
            continue;
        }
        String key = pair.getKey();
        if (key == null) {
            continue;
        }
        String value = pair.getValue();
        if (value == null) {
            json.add(key, JsonNull.INSTANCE);
        } else {
            json.addProperty(key, value);
        }
    }
    return json;
}

protected int removeUnusedNodes() {
    int removedCount = 0;
    try {
        // Assume there is a field named 'root' of type Category
        if (root == null) {
            return 0;
        }
        // If the root itself is inactive, remove the entire tree
        if (!root.isActive()) {
            root = null;
            return 1;
        }
        removedCount = removeInactiveRecursively(root);
    } catch (Exception e) {
        // Basic error reporting; replace with proper logging if available
        System.err.println("Error while removing unused nodes: " + e.getMessage());
    }
    return removedCount;
}

private int removeInactiveRecursively(Category node) {
    int count = 0;
    List<Category> children = node.getChildren();
    if (children == null || children.isEmpty()) {
        return 0;
    }
    // Work on a copy to avoid ConcurrentModificationException
    List<Category> copy = new ArrayList<>(children);
    for (Category child : copy) {
        if (!child.isActive()) {
            try {
                node.removeChild(child);
                count++;
            } catch (Exception e) {
                System.err.println("Failed to remove child: " + e.getMessage());
            }
        } else {
            count += removeInactiveRecursively(child);
        }
    }
    return count;
}

