public int decide(LoggingEvent event){
    if (event == null) {
        return Filter.NEUTRAL;
    }
    String msg = event.getMessage();
    if (msg == null) {
        return Filter.NEUTRAL;
    }
    if (regex == null) {
        return Filter.NEUTRAL;
    }
    try {
        if (regex.matcher(msg).find()) {
            return Filter.ACCEPT;
        }
    } catch (Exception e) {
        // If regex matching fails, treat as no match
    }
    return Filter.NEUTRAL;
}

