private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparators = new ArrayList<>();
    // If the graph is not initialized, return an empty list
    if (graph == null) {
        return globalSeparators;
    }
    try {
        // Iterate over all edges in the graph
        for (E edge : graph.getEdges()) {
            if (edge == null) {
                continue; // skip null edges
            }
            // Compute minimal separators for the current edge
            List<Pair<Integer,Integer>> separators = computeMinimalSeparatorsForEdge(edge);
            if (separators == null) {
                separators = new ArrayList<>(); // avoid null list
            }
            // Add the pair (separators, edge) to the global list
            globalSeparators.add(new Pair<>(separators, edge));
        }
    } catch (Exception ex) {
        // In case of any unexpected exception, return what has been collected so far
        // Optionally log the exception if a logger is available
    }
    return globalSeparators;
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    if (row < 0 || row >= table.getRowCount()) {
        return;
    }
    if (!SwingUtilities.isEventDispatchThread()) {
        SwingUtilities.invokeLater(() -> selectRow(row, table, pane));
        return;
    }
    table.setRowSelectionInterval(row, row);
    Rectangle cellRect = table.getCellRect(row, 0, true);
    if (cellRect != null) {
        table.scrollRectToVisible(cellRect);
    }
    SwingUtilities.invokeLater(() -> table.repaint());
}

public ByteVector putInt(final int intValue){
    int loc0 = this.length;
    if (loc0 + 4 > this.data.length) {
        enlarge(4);
    }
    byte[] loc1 = this.data;
    loc1[loc0++] = (byte)(intValue >>> 24);
    loc1[loc0++] = (byte)(intValue >>> 16);
    loc1[loc0++] = (byte)(intValue >>> 8);
    loc1[loc0++] = (byte)intValue;
    this.length = loc0;
    return this;
}

public static boolean arrayequals(byte[] a, byte[] b, int count) {
    // Handle trivial cases
    if (count == 0) {
        return true;
    }
    if (count < 0) {
        return false;
    }
    if (a == null || b == null) {
        return false;
    }
    // Ensure arrays are long enough
    if (a.length < count || b.length < count) {
        return false;
    }
    // Compare byte by byte
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    if (buf == null) {
        throw new IllegalArgumentException("buf cannot be null");
    }
    if (name == null) {
        return;
    }
    if (nameStart < 0 || nameStart >= name.length()) {
        return;
    }
    boolean startOfWord = true;
    for (int i = nameStart; i < name.length(); i++) {
        char ch = name.charAt(i);
        if (Character.isWhitespace(ch)) {
            startOfWord = true;
            continue;
        }
        if (startOfWord) {
            buf.append(ch);
            buf.append('.');
            startOfWord = false;
        }
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable){
    if (typeVariable == null) {
        return Unknown.class;
    }
    Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0) {
        return Unknown.class;
    }
    Type bound = bounds[0];
    return bound != null ? bound : Unknown.class;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    if (vertices.size() <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        if (v1 == null) {
            return false;
        }
        for (V v2 : vertices) {
            if (v1 == v2) {
                continue;
            }
            if (v2 == null) {
                return false;
            }
            try {
                if (graph.getEdge(v1, v2) == null) {
                    return false;
                }
            } catch (Exception e) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) {
        return bounds;
    }
    for (K key : keys) {
        if (key == null) {
            bounds.add(null);
            continue;
        }
        Integer current;
        try {
            current = (Integer) key;
        } catch (ClassCastException e) {
            throw new IllegalArgumentException("All keys must be of type Integer", e);
        }
        Integer maxLower = null;
        for (K other : keys) {
            if (other == null || other == key) {
                continue;
            }
            Integer val;
            try {
                val = (Integer) other;
            } catch (ClassCastException e) {
                throw new IllegalArgumentException("All keys must be of type Integer", e);
            }
            if (val < current) {
                if (maxLower == null || val > maxLower) {
                    maxLower = val;
                }
            }
        }
        bounds.add(maxLower);
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys cannot be null");
    }
    List<Integer> bounds = new ArrayList<>(keys.size());
    for (K key : keys) {
        if (key == null) {
            throw new IllegalArgumentException("key cannot be null");
        }
        bounds.add(key.hashCode());
    }
    return bounds;
}

