public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    boolean leadingSlash = path.startsWith("/");
    boolean trailingSlash = path.endsWith("/");
    java.util.List<String> parts = new java.util.ArrayList<>();
    for (String p : path.split("/")) {
        if (!p.isEmpty()) {
            parts.add(p);
        }
    }
    for (String p : relativePath.split("/")) {
        if (p.isEmpty() || p.equals(".")) {
            continue;
        } else if (p.equals("..")) {
            if (!parts.isEmpty()) {
                parts.remove(parts.size() - 1);
            }
        } else {
            parts.add(p);
        }
    }
    StringBuilder sb = new StringBuilder();
    if (leadingSlash) {
        sb.append("/");
    }
    for (int i = 0; i < parts.size(); i++) {
        sb.append(parts.get(i));
        if (i < parts.size() - 1) {
            sb.append("/");
        }
    }
    if (trailingSlash && sb.length() > 0 && sb.charAt(sb.length() - 1) != '/') {
        sb.append("/");
    }
    if (sb.length() == 0) {
        return ".";
    }
    return sb.toString();
}

