static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int count = 0;
    for (Object o : array) {
        if (o != null) {
            count++;
        }
    }
    if (count == array.length) {
        if (array instanceof String[]) {
            return (String[]) array;
        }
    }
    String[] result = new String[count];
    int idx = 0;
    for (Object o : array) {
        if (o != null) {
            result[idx++] = (String) o;
        }
    }
    return result;
}

