public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IOException("File does not exist or is not a regular file: " + file);
    }
    boolean filter = timeRanges != null && !timeRanges.isEmpty();
    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            ThreadSnapshot snapshot;
            try {
                snapshot = ThreadSnapshot.parse(line);
            } catch (Exception e) {
                // Skip malformed lines
                continue;
            }
            if (!filter) {
                result.add(snapshot);
                continue;
            }
            long ts = snapshot.getTimestamp();
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (ts >= range.getStart() && ts <= range.getEnd()) {
                    result.add(snapshot);
                    break;
                }
            }
        }
    }
    return result;
}
